return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'fur','project-id-version'=>'babilim-0.1.0-fur-babilim-0.1.0-fur-20261030T024047','pot-creation-date'=>'2026-10-30T06:25:26+00:00','po-revision-date'=>'2026-10-30T06:25:26+00:00','x-generator'=>'Babilim','messages'=>['Babilim'=>'Babilim','Fills in missing translations for the plugins and themes already installed on your site.'=>'Al jemple lis traduzions che a mancjin pai plugins e pai temis za instalâts sul to sît.','Translations'=>'Traduzions','Babilim Settings'=>'Impostazions di Babilim','Settings'=>'Impostazions','You are not allowed to do this.'=>'No tu às il permès di fâ cheste operazion.','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'Selezione mancul component: al massim %1$d operazions par esecuzion (tu âs selezionât %2$d).','That component is not installed on this site, so a translation cannot be requested for it.'=>'Chest component nol è instalât su chest sît, duncje no si pues domandâ une traduzion par lui.','Already installed.'=>'Za instalât.','Downloaded and installed.'=>'Discjariât e instalât.','Babilim has not been enabled for this site yet.'=>'Babilim nol è ancjemò stât ativât par chest sît.','No build is available to download for this locale.'=>'Nissun build disponibil par discjariâ par cheste lenghe.','Rolled back to the previous build.'=>'Tornât al build precedent.','Rolled back and reported.'=>'Tornât indaûr e segnalât.','Rolled back, but the report could not be sent: %s'=>'Tornât indaûr, ma la segnalazion no si à podût mandâ: %s','Removed.'=>'Gjavât.','Translation requested.'=>'Traduzion domandade.','This component was already uploaded. Babilim is checking it now.'=>'Chest component al jere za stât cjariât. Babilim lu sta controlant cumò.','Upload cancelled.'=>'Cjariament anulât.','Upload complete — translation requested.'=>'Cjariament completât — traduzion domandade.','This component does not declare a version number, so a translation cannot be requested for it.'=>'Chest component nol declare un numar di version, duncje no si pues domandâ une traduzion par lui.','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'Il numar di version di chest component al è plui lunc di %d caratars, che Babilim no rive a gjestî, duncje no si pues domandâ une traduzion par lui.','A translation cannot be requested for that locale on this site right now.'=>'Par cumò no si pues domandâ une traduzion par cheste lenghe su chest sît.','Thank you. Your report was sent.'=>'Graziis. La tô segnalazion e je stade mandade.','This report does not name a valid plugin or theme and locale.'=>'Cheste segnalazion no indiche un plugin o un teme e une lenghe valits.','Please choose a category for this report.'=>'Sielç une categorie par cheste segnalazion.','This report is missing a valid build to report against.'=>'A cheste segnalazion i mancje un build valid su cui fâ la segnalazion.','This build is not one this site currently knows about for this component/locale.'=>'Chest build nol è un che chest sît al cognòs par chest component/lenghe.','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'Il cjamp "%1$s" al è masse lunc: al à %2$d caratars e il limit al è %3$d. Nol è stât mandât nuie; scurtilu e prove di gnûf.','Original string'=>'Stringhe origjinâl','String context'=>'Contest de stringhe','Current translation'=>'Traduzion atuâl','Suggested translation'=>'Traduzion sugjeride','Note (optional)'=>'Note (opzionâl)','Where you saw this (optional)'=>'Dulà che tu âs viodût chest (opzionâl)','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'La sincronizazion di Babilim e je ritardade temporaneamentri dal servizi (limit di richiestis); e tornarà a provâ dopo %s.','The locale you added is not valid: use a WordPress locale 